const D = { density:.5, energy:.55, hue:255, speed:1, scale:1, x:.72, y:.28, style:'nebula', act:'drift', seed:0, planets:.5 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const md=(a,n)=>((a%n)+n)%n, frc=v=>v-Math.floor(v), clp=(v,a,b)=>Math.max(a,Math.min(b,v)), TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const H=md(P.hue,360);
const style=P.style;
const wireframe=style==='wireframe', spectral=style==='spectral', pulp=style==='pulp', voyager=style==='voyager';
const en=clp(P.energy,0,1)*(.5+.6*K.intensity);
const dens=clp(P.density,0,1);
const W=width, Ht=height, u=Math.min(W,Ht);
const t=K.t||0;

// ---- static deep-field buffer keyed on size + seed + style ----
const key=W+'x'+Ht+'|'+P.seed+'|'+style;
if(!S.bg || S.key!==key){
  S.key=key;
  const g=createGraphics(W,Ht); g.colorMode(HSB,360,100,100,100); g.noStroke();
  g.fill(voyager?0:md(H+10,360), voyager?0:50, voyager?8:9); g.rect(0,0,W,Ht);
  if(!wireframe){
    g.push(); g.blendMode(ADD);
    for(let i=0;i<80;i++){
      const x=fr(i*3.1)*W, y=fr(i*7.7)*Ht, r=(40+fr(i*2.3)*150)*(u/620);
      const nh = voyager?0 : md(H + (fr(i*5.5)-.5)*120, 360);
      const ns = voyager?0 : (spectral? 80 : 60);
      const nb = pulp? 22 : (spectral? 26 : 16);
      g.fill(nh,ns,nb, 5); g.ellipse(x,y,r,r);
    }
    g.pop();
  } else {
    g.stroke(md(H,360),40,26,30); g.strokeWeight(1);
    for(let x=0;x<W;x+=Math.max(40,u*0.08)) g.line(x,0,x,Ht);
    for(let y=0;y<Ht;y+=Math.max(40,u*0.08)) g.line(0,y,W,y);
    g.noStroke();
  }
  const nStar= voyager?200:260;
  for(let i=0;i<nStar;i++){
    const x=fr(i*8.9)*W, y=fr(i*15.1)*Ht, s=(fr(i*2.1)*1.4+0.3)*(u/620);
    g.fill(0,0,66+fr(i*5)*34, 78); g.ellipse(x,y,s,s);
  }
  S.bg=g;
  const arms=[]; const nA=140;
  for(let a=0;a<nA;a++){ const ang=a*0.16, rad=a*0.9; arms.push([ang,rad, a]); }
  S.arms=arms;
}
if(S.seedUsed!==P.seed){ S.seedUsed=P.seed; }
image(S.bg,0,0);

// ---- live layer ----
const warp = P.act==='warp';
const orbit = P.act==='orbit';
const cx=W*clp(P.x,0,1), cy=Ht*clp(P.y,0,1);

// slow parallax drift of everything (real-time floor, never re-phases)
const drx=Math.sin(t*0.05)*u*0.02, dry=Math.cos(t*0.037)*u*0.016;

// ---- MOTION FLOOR 1: drifting nebula gas (painterly styles) ----
// Large soft additive clouds whose centers travel on incommensurate real-time
// frequencies. Big-area brightness changes carry the motion gate with zero audio.
if(!wireframe){
  push(); blendMode(ADD);
  const nG=6;
  for(let i=0;i<nG;i++){
    const fx=0.5 + Math.sin(t*(0.045+fr(i*2.1)*0.06) + i*1.3)*0.42;
    const fy=0.5 + Math.cos(t*(0.038+fr(i*3.3)*0.055) + i*2.1)*0.42;
    const gx=fx*W, gy=fy*Ht;
    const gr=(0.34+fr(i*4.7)*0.34)*u*(0.75+dens*0.6);
    const gh= voyager?0 : md(H + (fr(i*5.5)-.5)*110, 360);
    const gs= voyager?0 : (spectral?85:55);
    const gb= (pulp?24:20)+16*en;
    fill(gh,gs,gb, 6+5*en);
    ellipse(gx,gy,gr,gr);
  }
  noStroke(); pop();
}

// ---- MOTION FLOOR 2: bright twinkling stars (works in ALL styles) ----
// Per-star continuous real-time phase; over 8s each phase advances many radians
// so brightness is decorrelated t vs t+8. Style-independent (brightness gate).
push(); blendMode(ADD);
const nTw=Math.round((warp?150:190)*(0.35+dens));
for(let i=0;i<nTw;i++){
  const bx=fr(i*4.7)*W + drx*(0.5+fr(i)*1.5), by=fr(i*9.3)*Ht + dry*(0.5+fr(i)*1.5);
  const tw=0.5+0.5*Math.sin(t*(1.1+fr(i*2)*2.6) + i*1.7);
  const sh= voyager?0 : (spectral? md(H+(fr(i)-.5)*160,360) : md(H+ (fr(i*3)-.5)*40,360));
  const ss= voyager?0 : 26;
  if(warp){
    const ang=Math.atan2(by-cy,bx-cx), len=(8+fr(i*2)*54)*(0.4+en)*(u/620);
    stroke(sh,ss,100,55*tw); strokeWeight((0.9+fr(i)*1.6)*(u/620));
    line(bx,by, bx+Math.cos(ang)*len, by+Math.sin(ang)*len);
  } else {
    const s=(1.4+fr(i*5.5)*3.4)*(u/620)*(0.35+tw);
    noStroke(); fill(sh,ss,100, (34+52*tw));
    ellipse(bx,by,s,s);
    if(tw>0.8 && !pulp){ stroke(sh,ss,100,52*tw); strokeWeight(0.9*(u/620)); const d=s*2.4; line(bx-d,by,bx+d,by); line(bx,by-d,bx,by+d); noStroke(); }
  }
}
noStroke(); pop();

// ---- MOTION FLOOR 3 (wireframe): rotating concentric wire rings ----
if(wireframe){
  push(); translate(W*0.5+drx, Ht*0.5+dry); blendMode(BLEND);
  noFill();
  for(let m=0;m<5;m++){
    push(); rotate(t*(0.05+m*0.03)*(1+en) + m*0.6);
    stroke(md(H,360),42,78,30+m*6); strokeWeight(1);
    ellipse(0,0, u*(0.42+m*0.16), u*(0.24+m*0.13));
    pop();
  }
  // sweeping radar line
  push(); rotate(t*0.5*(0.6+en)); stroke(md(H+30,360),40,92,55); strokeWeight(1.4);
  line(0,0,u*0.72,0); pop();
  pop();
}

// ---- GALAXY spiral: rotates continuously on real-time t (big-area motion) ----
push(); translate(cx+drx, cy+dry);
const rot=t*0.07*P.speed + (orbit?t*0.07:0);
rotate(rot);
blendMode(wireframe?BLEND:ADD);
const arms=S.arms||[];
const step= wireframe?2:1;
const glowP=(0.5+0.5*K.swell)*en + A.mid*0.5;
const gScale=(u/620)*(0.85+P.planets*0.5);
for(let a=0;a<arms.length;a+=step){
  const ang=arms[a][0], rad=arms[a][1]*gScale;
  const gh= voyager?0 : md(H + arms[a][2]*0.6, 360);
  const gb= 62+32*glowP;
  if(wireframe){ stroke(md(H,360),42,82,44); strokeWeight(1.2); noFill(); }
  else { noStroke(); fill(gh, voyager?0:55, gb, 26); }
  const dsz=(wireframe?1:4)*(u/620)*(1+0.4*Math.sin(t*0.7+a*0.3));
  const x1=Math.cos(ang)*rad, y1=Math.sin(ang)*rad*0.5;
  const x2=Math.cos(ang+Math.PI)*rad, y2=Math.sin(ang+Math.PI)*rad*0.5;
  if(wireframe){ point(x1,y1); point(x2,y2); }
  else { ellipse(x1,y1,dsz,dsz); ellipse(x2,y2,dsz,dsz); }
}
if(!wireframe){ blendMode(ADD); fill(voyager?0:md(H+30,360), voyager?0:30, 100, 34); const cr=u*0.12*(0.6+glowP); ellipse(0,0,cr,cr); }
pop();

// ---- RINGED PLANET: slow orbit / rotation ----
push();
const pOrb = orbit? t*0.09 : t*0.03;
const px=W*0.22 + Math.cos(pOrb)*u*0.05, py=Ht*0.64 + Math.sin(pOrb)*u*0.035;
translate(px,py);
const pr=u*0.14*(0.6+P.planets*0.8);
if(wireframe){
  noFill(); stroke(md(H+40,360),40,90,72); strokeWeight(1.2);
  ellipse(0,0,pr,pr);
  for(let m=0;m<5;m++){ const e=pr*(0.3+m*0.16); push(); rotate(t*0.12+m); ellipse(0,0,pr, e); pop(); }
  push(); rotate(-0.4); ellipse(0,0,pr*1.8,pr*0.6); pop();
} else {
  noStroke();
  const ph=voyager?0:md(H+40,360), ps=voyager?0:70;
  fill(ph,ps,74); ellipse(0,0,pr,pr);
  fill(ph,ps,30,60); arc(0,0,pr,pr,-Math.PI*0.5+0.4, Math.PI*0.5+0.4, PIE);
  push(); rotate(-0.4+Math.sin(t*0.12)*0.03); noFill(); stroke(voyager?0:md(H+50,360),voyager?0:50,92,72); strokeWeight(pr*0.06); ellipse(0,0,pr*1.9,pr*0.62); pop();
}
pop();
noStroke();

// ---- occasional SHOOTING STAR ----
if(!warp){
  const ssT=frc(t*0.08);
  if(ssT<0.14){
    const life=ssT/0.14; const seedIdx=Math.floor(t*0.08);
    const sx=fr(seedIdx*3.1)*W, sy=fr(seedIdx*7.7)*Ht*0.6;
    const ex=sx+u*0.4, ey=sy+u*0.2;
    const hx=sx+(ex-sx)*life, hy=sy+(ey-sy)*life;
    push(); blendMode(ADD); stroke(0,0,100,60*(1-life)); strokeWeight(2*(u/620));
    line(hx-u*0.06,hy-u*0.03,hx,hy); pop();
  }
}

blendMode(BLEND);
